insert into public.topics
  (id, slug, name, short_description, long_description, curriculum_order, stage)
values
  ('10000000-0000-4000-8000-000000000001', 'interview-fundamentals', 'Interview Fundamentals', 'Build a repeatable interview process before solving harder algorithms.', 'Learn how to clarify requirements, communicate a baseline solution, improve it deliberately, and test the result like a collaborative engineer.', 1, 0),
  ('10000000-0000-4000-8000-000000000002', 'big-o', 'Big-O', 'Reason clearly about time, space, and scalability tradeoffs.', 'Use input growth and operation counts to compare approaches, communicate tradeoffs, and catch accidental performance problems.', 2, 1),
  ('10000000-0000-4000-8000-000000000003', 'programming-foundations', 'Programming Foundations', 'Strengthen the language and data-structure mechanics used in interviews.', 'Practice loops, functions, collections, recursion basics, and precise state changes so implementation does not hide the algorithm.', 3, 1),
  ('10000000-0000-4000-8000-000000000004', 'arrays-and-hashing', 'Arrays & Hashing', 'Turn repeated scans into direct lookups and useful summaries.', 'Use arrays, strings, sets, and hash maps to count, group, deduplicate, and remember information while scanning an input.', 4, 2),
  ('10000000-0000-4000-8000-000000000005', 'two-pointers', 'Two Pointers', 'Coordinate two positions to avoid unnecessary nested loops.', 'Recognize sorted, paired, partitioned, or in-place problems where two coordinated indices shrink the search space.', 5, 2),
  ('10000000-0000-4000-8000-000000000006', 'sliding-window', 'Sliding Window', 'Maintain a contiguous range without recomputing every candidate.', 'Solve fixed and variable contiguous-range problems by updating only the information that enters or leaves the current window.', 6, 2),
  ('10000000-0000-4000-8000-000000000007', 'stack', 'Stack', 'Use last-in-first-out state to resolve nested and monotonic structure.', 'Model unmatched work, nested syntax, undo-like behavior, and nearest-boundary questions with explicit or monotonic stacks.', 7, 2),
  ('10000000-0000-4000-8000-000000000008', 'binary-search', 'Binary Search', 'Exploit monotonic structure to discard half the search space.', 'Search sorted data and monotonic answer spaces with a loop invariant that makes boundaries and termination predictable.', 8, 2),
  ('10000000-0000-4000-8000-000000000009', 'linked-list', 'Linked List', 'Rewire node relationships safely with a small set of pointers.', 'Use sentinel nodes, fast and slow pointers, and local invariants to traverse, reverse, merge, and detect cycles.', 9, 2),
  ('10000000-0000-4000-8000-000000000010', 'trees', 'Trees', 'Traverse hierarchical data with purposeful DFS and BFS state.', 'Translate recursive structure into base cases, combine child results, and choose depth-first or breadth-first traversal intentionally.', 10, 2),
  ('10000000-0000-4000-8000-000000000011', 'heap-priority-queue', 'Heap / Priority Queue', 'Keep the most relevant candidate available as data changes.', 'Use bounded heaps and priority queues for top-k, streaming extrema, scheduling, and repeated best-candidate selection.', 11, 2),
  ('10000000-0000-4000-8000-000000000012', 'backtracking', 'Backtracking', 'Explore choices while undoing state cleanly.', 'Build decision trees for combinations, permutations, and constraint search using choose, explore, and unchoose.', 12, 3),
  ('10000000-0000-4000-8000-000000000013', 'graphs', 'Graphs', 'Model arbitrary connections and traverse them without revisiting work.', 'Represent connections, track visited state, and apply DFS, BFS, and component reasoning to graph and grid problems.', 13, 3),
  ('10000000-0000-4000-8000-000000000014', 'tries', 'Tries', 'Index strings by shared prefixes.', 'Use prefix trees when repeated prefix queries, dictionary exploration, or character-by-character pruning matters.', 14, 3),
  ('10000000-0000-4000-8000-000000000015', 'intervals', 'Intervals', 'Reason about overlapping ranges after ordering their boundaries.', 'Sort, merge, insert, and schedule ranges by stating clearly what overlap and compatibility mean.', 15, 3),
  ('10000000-0000-4000-8000-000000000016', 'greedy', 'Greedy', 'Make locally useful choices when an exchange argument supports them.', 'Recognize when a locally optimal decision preserves a globally optimal solution and when greedy reasoning is unsafe.', 16, 3),
  ('10000000-0000-4000-8000-000000000017', 'one-dimensional-dp', '1-D Dynamic Programming', 'Reuse answers to overlapping one-dimensional subproblems.', 'Define state, transition, base cases, and evaluation order for sequence and take-or-skip decisions.', 17, 4),
  ('10000000-0000-4000-8000-000000000018', 'two-dimensional-dp', '2-D Dynamic Programming', 'Track subproblems that need two changing coordinates.', 'Design grid, string-pair, and two-state dynamic programs while controlling memory and transition complexity.', 18, 4),
  ('10000000-0000-4000-8000-000000000019', 'advanced-graphs', 'Advanced Graphs', 'Apply ordering, shortest-path, and connectivity algorithms deliberately.', 'Choose topological sorting, union-find, Dijkstra, or minimum-spanning-tree techniques from graph constraints and edge semantics.', 19, 4),
  ('10000000-0000-4000-8000-000000000020', 'bit-manipulation', 'Bit Manipulation', 'Use binary representations for compact state and low-level invariants.', 'Recognize XOR cancellation, bit masks, shifts, and per-bit counting without turning code into unexplained tricks.', 20, 4),
  ('10000000-0000-4000-8000-000000000021', 'math-and-geometry', 'Math & Geometry', 'Translate numeric and spatial constraints into stable formulas.', 'Use modular arithmetic, coordinate reasoning, counting, and careful overflow or precision handling in interview problems.', 21, 4);
