insert into public.lessons
  (id, topic_id, slug, title, lesson_order, estimated_minutes, learning_objectives, recognition_signals, common_mistakes, content_path)
values
  ('20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000001', 'interview-loop', 'The interview problem-solving loop', 1, 18, array['Clarify a prompt before coding', 'Present a baseline and improve it', 'Test with deliberate cases'], array['ambiguous requirements', 'tradeoff discussion', 'edge cases', 'communication'], array['coding before confirming assumptions', 'hiding the brute-force baseline', 'testing only the happy path'], 'content/curriculum/interview-fundamentals.md'),
  ('20000000-0000-4000-8000-000000000002', '10000000-0000-4000-8000-000000000002', 'complexity-essentials', 'Complexity that guides decisions', 1, 22, array['Estimate time and space from code', 'Compare growth rates', 'Explain complexity with relevant variables'], array['input grows', 'nested work', 'sorting cost', 'memory tradeoff'], array['dropping meaningful variables', 'counting syntax instead of operations', 'ignoring auxiliary space'], 'content/curriculum/big-o.md'),
  ('20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000003', 'implementation-basics', 'Implementation foundations', 1, 24, array['Choose appropriate collections', 'Trace state changes', 'Use recursion with explicit base cases'], array['counting or grouping', 'repeated state update', 'recursive structure'], array['mutating while iterating unexpectedly', 'unclear variable invariants', 'missing recursion base cases'], 'content/curriculum/programming-foundations.md'),
  ('20000000-0000-4000-8000-000000000004', '10000000-0000-4000-8000-000000000004', 'lookup-and-counting', 'Lookups, counting, and grouping', 1, 28, array['Replace repeated scans with hash lookups', 'Choose between a set and map', 'State time-space tradeoffs'], array['duplicate', 'frequency', 'pair or complement', 'group by key', 'membership'], array['checking before updating in the wrong order', 'using a map when a set is enough', 'assuming iteration order'], 'content/curriculum/arrays-and-hashing.md'),
  ('20000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000000005', 'coordinated-indices', 'Coordinated indices', 1, 26, array['Recognize two-pointer structure', 'Choose pointer movement from an invariant', 'Handle same-direction and opposite-direction variants'], array['sorted input', 'pair', 'opposite ends', 'palindrome', 'in-place partition'], array['moving both pointers without justification', 'missing equality cases', 'losing required values during overwrite'], 'content/curriculum/two-pointers.md'),
  ('20000000-0000-4000-8000-000000000006', '10000000-0000-4000-8000-000000000006', 'maintaining-a-window', 'Maintaining a useful window', 1, 30, array['Separate fixed and variable windows', 'Maintain incremental window state', 'Prove when the left boundary moves'], array['contiguous', 'substring', 'subarray', 'longest', 'shortest', 'at most k', 'fixed length'], array['recomputing the whole window', 'shrinking with if instead of while', 'updating the answer before validity'], 'content/curriculum/sliding-window.md'),
  ('20000000-0000-4000-8000-000000000007', '10000000-0000-4000-8000-000000000007', 'stack-invariants', 'Stack invariants', 1, 27, array['Model unresolved work with a stack', 'Recognize monotonic stack questions', 'Explain push and pop invariants'], array['nested structure', 'matching pairs', 'next greater', 'nearest smaller', 'undo'], array['popping without using the value', 'storing values when indices are needed', 'forgetting unresolved items'], 'content/curriculum/stack.md'),
  ('20000000-0000-4000-8000-000000000008', '10000000-0000-4000-8000-000000000008', 'search-boundaries', 'Search boundaries without guesswork', 1, 29, array['Write a loop invariant', 'Choose closed or half-open boundaries', 'Search a monotonic answer space'], array['sorted', 'first or last valid', 'minimum feasible', 'maximum possible', 'monotonic predicate'], array['mixing boundary conventions', 'not making progress', 'returning the last midpoint blindly'], 'content/curriculum/binary-search.md'),
  ('20000000-0000-4000-8000-000000000009', '10000000-0000-4000-8000-000000000009', 'pointer-rewiring', 'Safe pointer rewiring', 1, 27, array['Use sentinel nodes', 'Reverse links without losing the remainder', 'Apply fast and slow pointers'], array['in-place reversal', 'cycle', 'middle node', 'merge chains', 'remove node'], array['overwriting next before saving it', 'special-casing the head repeatedly', 'dereferencing beyond the list'], 'content/curriculum/linked-list.md'),
  ('20000000-0000-4000-8000-000000000010', '10000000-0000-4000-8000-000000000010', 'tree-traversal', 'Purposeful tree traversal', 1, 32, array['Choose DFS or BFS from the question', 'Define recursive return meaning', 'Combine child results correctly'], array['hierarchy', 'root-to-leaf', 'level order', 'subtree result', 'ancestor'], array['recursing without a return contract', 'mixing node and edge depth', 'using global state unnecessarily'], 'content/curriculum/trees.md'),
  ('20000000-0000-4000-8000-000000000011', '10000000-0000-4000-8000-000000000011', 'top-k-and-priorities', 'Top-k and changing priorities', 1, 22, array['Choose min-heap or max-heap', 'Maintain a bounded top-k heap', 'Analyze heap operation costs'], array['top k', 'kth largest', 'streaming minimum or maximum', 'schedule next'], array['using the wrong heap direction', 'keeping every item unnecessarily', 'claiming heap operations are constant'], 'content/curriculum/heap-priority-queue.md'),
  ('20000000-0000-4000-8000-000000000012', '10000000-0000-4000-8000-000000000012', 'decision-trees', 'Decision trees and clean state', 1, 26, array['Model choices as a tree', 'Use choose-explore-unchoose', 'Prune invalid branches'], array['all combinations', 'all permutations', 'constraint search', 'generate arrangements'], array['forgetting to undo shared state', 'adding mutable paths by reference', 'failing to prune'], 'content/curriculum/backtracking.md'),
  ('20000000-0000-4000-8000-000000000013', '10000000-0000-4000-8000-000000000013', 'graph-traversal', 'Graph traversal and visited state', 1, 28, array['Build an adjacency representation', 'Use visited state correctly', 'Count components with DFS or BFS'], array['network', 'connections', 'reachable', 'components', 'grid as graph'], array['marking visited too late', 'assuming a graph is connected', 'confusing nodes with edges'], 'content/curriculum/graphs.md'),
  ('20000000-0000-4000-8000-000000000014', '10000000-0000-4000-8000-000000000014', 'prefix-trees', 'Prefix trees', 1, 18, array['Build trie nodes', 'Distinguish words from prefixes', 'Use prefix pruning'], array['prefix search', 'dictionary', 'autocomplete', 'many word queries'], array['not marking word endings', 'creating nodes during lookup', 'using a trie for one lookup'], 'content/curriculum/tries.md'),
  ('20000000-0000-4000-8000-000000000015', '10000000-0000-4000-8000-000000000015', 'overlap-and-ordering', 'Overlap and ordering', 1, 20, array['Define overlap precisely', 'Sort by the useful boundary', 'Merge or schedule intervals'], array['time ranges', 'overlap', 'merge', 'meeting rooms', 'non-overlapping'], array['using an inconsistent endpoint convention', 'sorting by the wrong boundary', 'forgetting the final interval'], 'content/curriculum/intervals.md'),
  ('20000000-0000-4000-8000-000000000016', '10000000-0000-4000-8000-000000000016', 'safe-greedy-choices', 'When a greedy choice is safe', 1, 20, array['State the local choice', 'Sketch an exchange argument', 'Recognize greedy counterexamples'], array['maximize count', 'earliest finish', 'local choice', 'one pass optimum'], array['calling any local heuristic greedy', 'skipping the correctness argument', 'using greedy when choices affect future feasibility'], 'content/curriculum/greedy.md'),
  ('20000000-0000-4000-8000-000000000017', '10000000-0000-4000-8000-000000000017', 'state-and-transition', 'State, transition, and order', 1, 24, array['Define a one-dimensional state', 'Write transitions from smaller states', 'Compress memory safely'], array['count ways', 'minimum cost', 'take or skip', 'overlapping subproblems'], array['starting with a table before defining state', 'incorrect base cases', 'overwriting values still needed'], 'content/curriculum/one-dimensional-dp.md'),
  ('20000000-0000-4000-8000-000000000018', '10000000-0000-4000-8000-000000000018', 'two-coordinate-states', 'Two-coordinate states', 1, 24, array['Define a two-dimensional state', 'Order grid or string-pair transitions', 'Estimate state-space cost'], array['two strings', 'grid paths', 'two changing indices', 'edit operations'], array['unclear state meaning', 'off-by-one table dimensions', 'ignoring quadratic space'], 'content/curriculum/two-dimensional-dp.md'),
  ('20000000-0000-4000-8000-000000000019', '10000000-0000-4000-8000-000000000019', 'specialized-graph-tools', 'Choosing specialized graph tools', 1, 25, array['Match constraints to a graph algorithm', 'Distinguish weighted and unweighted paths', 'Recognize dependency ordering'], array['dependencies', 'weighted shortest path', 'dynamic connectivity', 'minimum connection cost'], array['using BFS on arbitrary weights', 'ignoring stale priority-queue entries', 'missing cycle conditions'], 'content/curriculum/advanced-graphs.md'),
  ('20000000-0000-4000-8000-000000000020', '10000000-0000-4000-8000-000000000020', 'bits-as-state', 'Bits as compact state', 1, 18, array['Use masks for membership', 'Apply XOR cancellation', 'Test and update individual bits'], array['power of two', 'appears once', 'subset mask', 'binary flags'], array['using unexplained bit tricks', 'confusing signed shifts', 'missing operator precedence'], 'content/curriculum/bit-manipulation.md'),
  ('20000000-0000-4000-8000-000000000021', '10000000-0000-4000-8000-000000000021', 'numeric-and-spatial-reasoning', 'Numeric and spatial reasoning', 1, 20, array['Translate geometry into coordinates', 'Use modular arithmetic safely', 'Handle precision and overflow'], array['coordinates', 'angles', 'divisibility', 'large counts', 'modulo'], array['using floating point for exact equality', 'overflow before applying modulo', 'memorizing formulas without assumptions'], 'content/curriculum/math-and-geometry.md');
insert into public.lesson_prerequisites (lesson_id, prerequisite_lesson_id)
